public String convertToPageSql(String sql, Integer offset, Integer limit) {
    // Parse the SQL using JSQLParser
    Statement stmt;
    try {
        stmt = CCJSqlParserUtil.parse(sql);
    } catch (Exception e) {
        throw new PageException("不支持该SQL转换为分页查询!", e);
    }

    // Ensure the statement is a SELECT statement
    if (!(stmt instanceof Select)) {
        throw new PageException("分页语句必须是Select查询!");
    }

    Select select = (Select) stmt;
    PlainSelect plainSelect = (PlainSelect) select.getSelectBody();

    // Set limit if provided
    if (limit != null) {
        Limit sqlLimit = new Limit();
        sqlLimit.setRowCount(limit);
        plainSelect.setLimit(sqlLimit);
    }

    // Set offset if provided
    if (offset != null) {
        Offset sqlOffset = new Offset();
        sqlOffset.setOffset(offset);
        plainSelect.setOffset(sqlOffset);
    }

    return select.toString();
}

